1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	export interface ClaimStep {
19	  op: "claim";
20	  policy: number;
21	  incident: { cause: string; damages: Damage[] };
22	}
23	
24	export type Step = QuoteStep | ClaimStep;
25	
26	export interface Customer {
27	  yearsWithMHPCO: number;
28	}
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export interface QuoteResult {
36	  premium: number;
37	}
38	
39	export interface ClaimResult {
40	  payout: number;
41	  remainingCap: number;
42	}
43	
44	export interface ScenarioResults {
45	  results: (QuoteResult | ClaimResult)[];
46	}
47	
48	const PROCESSING_FEE = 5;
49	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
50	
51	const BASE_PREMIUMS = {
52	  sword: 100,
53	  amulet: 60,
54	  staff: 80,
55	  potion: 40,
56	  rune: 25,
57	  moonstone: 25,
58	} as const satisfies Record<string, number>;
59	
60	export type InsurableItemType = keyof typeof BASE_PREMIUMS;
61	
62	const basePremiumForType = (type: string): number =>
63	  BASE_PREMIUMS[type as InsurableItemType];
64	
65	const BLOCK_SIZE = 3;
66	const BLOCK_PREMIUM = 60;
67	
68	// Items of one type, quoted together. A group of exactly 3 forms a building
69	// block and is offered at a flat base premium; any other size is priced per
70	// item. "Alike" means the same item type — 2 runes + 1 moonstone is two
71	// groups, so neither is a block.
72	type AlikeGroup = [type: string, items: Item[]];
73	
74	const intoAlikeGroups = (items: Item[]): AlikeGroup[] => {
75	  const groups = new Map<string, Item[]>();
76	  for (const item of items) {
77	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
78	  }
79	  return [...groups];
80	};
81	
82	const isBuildingBlock = ([, items]: AlikeGroup): boolean =>
83	  items.length === BLOCK_SIZE;
84	
85	const basePremiumForGroup = (group: AlikeGroup): number => {
86	  const [type, items] = group;
87	  return isBuildingBlock(group)
88	    ? BLOCK_PREMIUM
89	    : items.length * basePremiumForType(type);
90	};
91	
92	const sumBasePremiums = (items: Item[]): number =>
93	  intoAlikeGroups(items).reduce(
94	    (total, group) => total + basePremiumForGroup(group),
95	    0,
96	  );
97	
98	const CURSE_SURCHARGE_RATE = 0.5;
99	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
100	const HIGH_ENCHANTMENT_THRESHOLD = 5;
101	
102	const isHighlyEnchanted = (item: Item): boolean =>
103	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
104	
105	// Item-specific modifiers apply to the base premium of the affected item, not
106	// to the policy total.
107	const surchargeRateForItem = (item: Item): number =>
108	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
109	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
110	
111	// Surcharges are charged against the item's own base premium, ignoring any
112	// building-block discount the item may be part of.
113	const surchargeForItem = (item: Item): number =>
114	  basePremiumForType(item.type) * surchargeRateForItem(item);
115	
116	const sumItemSurcharges = (items: Item[]): number =>
117	  items.reduce((total, item) => total + surchargeForItem(item), 0);
118	
119	// Premiums are rounded up, in the MHPCO's favour; only the final premium is
120	// rounded, intermediate amounts stay fractional.
121	const roundInMHPCOsFavour = Math.ceil;
122	
123	const LOYALTY_DISCOUNT_RATE = 0.2;
124	const LOYALTY_YEARS_THRESHOLD = 2;
125	
126	const isLoyal = (customer: Customer): boolean =>
127	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
128	
129	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
130	
131	// Policy-wide modifiers are summed into one net rate, not compounded. The net
132	// is signed: a loyal customer's discount can outweigh the surcharge.
133	//
134	// The first insurance surcharge applies to every quote — each item in a quote
135	// is treated as a first insurance, regardless of customer history — so it is
136	// not cancelled by the follow-up contract discount.
137	const policyModifierRateFor = (
138	  customer: Customer,
139	  precedingContracts: number,
140	): number =>
141	  FIRST_INSURANCE_SURCHARGE_RATE -
142	  (isLoyal(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
143	  (precedingContracts > 0 ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);
144	
145	// Charged against the policy base premium — the sum of all item base premiums —
146	// and added to it, mirroring how surchargeForItem works per item.
147	const policyModifierFor = (
148	  basePremium: number,
149	  customer: Customer,
150	  precedingContracts: number,
151	): number => basePremium * policyModifierRateFor(customer, precedingContracts);
152	
153	const quotePremium = (
154	  items: Item[],
155	  customer: Customer,
156	  precedingContracts: number,
157	): number => {
158	  const basePremium = sumBasePremiums(items);
159	  const itemSurcharges = sumItemSurcharges(items);
160	  const policyModifier = policyModifierFor(
161	    basePremium,
162	    customer,
163	    precedingContracts,
164	  );
165	  return roundInMHPCOsFavour(
166	    basePremium + itemSurcharges + policyModifier + PROCESSING_FEE,
167	  );
168	};
169	
170	// An item's insured worth, distinct from what it costs to insure.
171	const INSURANCE_VALUES = {
172	  sword: 1000,
173	  amulet: 600,
174	  staff: 800,
175	  potion: 400,
176	  rune: 250,
177	  moonstone: 250,
178	} as const satisfies Record<InsurableItemType, number>;
179	
180	const insuranceValueForType = (type: string): number =>
181	  INSURANCE_VALUES[type as InsurableItemType];
182	
183	const DEDUCTIBLE = 100;
184	const CAP_MULTIPLE = 2;
185	
186	// A quote step creates a policy; later claim steps refer to it by that step's
187	// index. The cap is consumed as claims are paid.
188	interface Policy {
189	  items: Item[];
190	  remainingCap: number;
191	}
192	
193	// The policy's total insured worth. Charged against the plain item values, so
194	// neither premium modifiers nor the building-block discount move it.
195	const insuranceSumFor = (items: Item[]): number =>
196	  items.reduce((sum, item) => sum + insuranceValueForType(item.type), 0);
197	
198	const openPolicy = (items: Item[]): Policy => ({
199	  items,
200	  remainingCap: CAP_MULTIPLE * insuranceSumFor(items),
201	});
202	
203	// Claims use their own, higher enchantment threshold — unrelated to the
204	// premium-side high-enchantment surcharge.
205	const REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
206	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
207	const FULL_REIMBURSEMENT_RATE = 1;
208	
209	const isHeavilyEnchanted = (item: Item): boolean =>
210	  (item.enchantment ?? 0) >= REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
211	
212	// Damage to a heavily enchanted item is only half reimbursed.
213	const reimbursementRateFor = (item: Item): number =>
214	  isHeavilyEnchanted(item)
215	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
216	    : FULL_REIMBURSEMENT_RATE;
217	
218	const damagedItem = (policy: Policy, damage: Damage): Item =>
219	  policy.items.find((item) => item.type === damage.itemType)!;
220	
221	// The reimbursement rate applies to the damage first; the deductible comes off
222	// what remains, once per damage event rather than once per claim.
223	const payoutForDamage = (policy: Policy, damage: Damage): number =>
224	  damage.amount * reimbursementRateFor(damagedItem(policy, damage)) -
225	  DEDUCTIBLE;
226	
227	// Settling a claim consumes the policy's cap, so the policy carries less cover
228	// into the next claim. Kept separate from settleClaim so the state change is
229	// visible where the policy is held rather than hidden behind a pure-looking call.
230	const consumeCap = (policy: Policy, result: ClaimResult): Policy => ({
231	  ...policy,
232	  remainingCap: result.remainingCap,
233	});
234	
235	const settleClaim = (policy: Policy, damages: Damage[]): ClaimResult => {
236	  const payout = damages.reduce(
237	    (total, damage) => total + payoutForDamage(policy, damage),
238	    0,
239	  );
240	  return { payout, remainingCap: policy.remainingCap - payout };
241	};
242	
243	const runStep = (
244	  step: Step,
245	  customer: Customer,
246	  precedingContracts: number,
247	  policies: Map<number, Policy>,
248	  stepIndex: number,
249	): QuoteResult | ClaimResult => {
250	  switch (step.op) {
251	    case "quote":
252	      policies.set(stepIndex, openPolicy(step.items));
253	      return { premium: quotePremium(step.items, customer, precedingContracts) };
254	    case "claim": {
255	      const policy = policies.get(step.policy)!;
256	      const result = settleClaim(policy, step.incident.damages);
257	      policies.set(step.policy, consumeCap(policy, result));
258	      return result;
259	    }
260	  }
261	};
262	
263	// Each quote in a scenario forms a contract, so every quote after the first is
264	// a follow-up. Steps are run in order and a step sees only the contracts that
265	// precede it. Only quote steps create contracts.
266	export const runScenario = (scenario: Scenario): ScenarioResults => {
267	  const results: (QuoteResult | ClaimResult)[] = [];
268	  const policies = new Map<number, Policy>();
269	  let contractsSoFar = 0;
270	  scenario.steps.forEach((step, stepIndex) => {
271	    results.push(
272	      runStep(step, scenario.customer, contractsSoFar, policies, stepIndex),
273	    );
274	    if (step.op === "quote") contractsSoFar += 1;
275	  });
276	  return { results };
277	};
